RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Emit every reconciliation difference and any financial snapshot change with `company_id`."
  # "Every check is keyed by `company_id`. No report or result mixes companies."
  it "emits difference events only with the company id of the company that changed" do
    entry_row = lambda do |id, company_id, note|
      {
        "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => note, "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => Time.utc(2026, 1, 5, 9), "updated_at" => Time.utc(2026, 1, 5, 9)
      }
    end
    checkpoint_of = lambda do |entries|
      tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }.merge("entries" => entries)
      Timekeeping::Handoff::Checkpoint.build(tables: tables)
    end
    projection_of = lambda do |row|
      row.merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch(row["bill_status"]),
        "review_status" => TimesheetEntry.review_statuses.fetch(row["review_status"])
      )
    end
    snapshot = ->(company_id) { { company_id: company_id, values: { [:invoice, 1, :discount] => BigDecimal("5") } } }
    collector = Class.new do
      attr_reader :events

      def initialize
        @events = []
      end

      def emit(event)
        @events << event
      end
    end.new

    loaded = [entry_row.call(1, 101, "secret-changed-note"), entry_row.call(1, 202, "same")]
    result = described_class.run(
      source: checkpoint_of.call([entry_row.call(1, 101, "same"), entry_row.call(1, 202, "same")]),
      checkpoint: checkpoint_of.call(loaded),
      projection: loaded.map { |row| projection_of.call(row) },
      source_intents: [],
      intents: [],
      next_entry_id: 1000,
      money_before: { 101 => snapshot.call(101), 202 => snapshot.call(202) },
      money_after: { 101 => snapshot.call(101), 202 => snapshot.call(202) }
    )

    Rails.event.subscribe(collector)
    begin
      described_class.report(result)
    ensure
      Rails.event.unsubscribe(collector)
    end

    found = collector.events.select { |event| event[:name] == "Timekeeping::ReconciliationDifferenceFound" }
    data = found.map { |event| event[:payload].to_h[:data] }
    expect(found.size).to eq(result.companies[101].checks.values.flatten.size)
    expect(found).not_to be_empty
    expect(data.pluck(:company_id).uniq).to eq([101])
    expect(JSON.generate(data)).not_to include("secret-changed-note")
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Emit every reconciliation difference and any financial snapshot change with `company_id`."
  it "emits the financial snapshot change only under the company whose after snapshot discount changed" do
    changed_company_id = 9_501
    unchanged_company_id = 9_502
    empty_tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
    empty_checkpoint = Timekeeping::Handoff::Checkpoint.build(tables: empty_tables)
    money_snapshot = lambda do |company_id, discount|
      { company_id:, values: { [:invoice, 77, :discount] => BigDecimal(discount) } }
    end

    result = described_class.run(
      source: empty_checkpoint,
      checkpoint: empty_checkpoint,
      projection: [],
      source_intents: [],
      intents: [],
      next_entry_id: 1,
      money_before: {
        changed_company_id => money_snapshot.call(changed_company_id, "5.00"),
        unchanged_company_id => money_snapshot.call(unchanged_company_id, "5.00")
      },
      money_after: {
        changed_company_id => money_snapshot.call(changed_company_id, "8642.00"),
        unchanged_company_id => money_snapshot.call(unchanged_company_id, "5.00")
      }
    )

    stored_events = RailsEventViewer::Entry.where(name: "Timekeeping::FinancialSnapshotChanged")
    expect { described_class.report(result) }.to change { stored_events.count }.by(1)

    data = stored_events.order(:id).last.payload["data"]
    expect(data["company_id"]).to eq(changed_company_id)
    expect([data["kind"].to_s, data["record_id"], data["field"].to_s]).to eq(["invoice", 77, "discount"])
    expect(JSON.generate(data)).not_to include("8642")
    expect(result.companies.fetch(changed_company_id)).to be_abort
    expect(result.companies.fetch(unchanged_company_id)).not_to be_abort
  end
end
